insert into public.vault_ideas (sort, category, status, year, hue, url, repo, images, title_zh, title_en, kind_zh, kind_en, line_zh, line_en, lead_zh, lead_en, tags_zh, tags_en, facts, tech, host) values (10, '3d', 'live', 2026, '#ff8a1f', 'https://sunset-citrus-harbor.vercel.app', null, array['assets/harbor-1.jpg','assets/harbor-2.jpg','assets/harbor-3.jpg','assets/harbor-4.jpg']::text[], '日落柑橘港', 'Sunset Citrus Harbor', '3D 交互场景', '3D interactive scene', '一座可以走进去的 3D 柑橘港湾，日落、夜景、清晨会自己流转。', 'A 3D citrus harbor you can walk into, drifting from sunset to night to dawn on its own.', '用 Three.js 程序化搭建的港湾主题公园，约 220×150 米，分柑橘集市、植物温室、灯塔高地、僵尸船坞、梯田小镇五个区域。可以总览环绕，也可以用第一或第三人称步行、飞行；喷泉、温室、灯塔、吊机、罐头厂靠近都能互动，还有在线排行榜和港湾留言。', 'A procedurally built harbor theme park in Three.js, about 220 × 150 m across five districts. Orbit the whole island, or walk and fly through it in first or third person. The fountain, greenhouse, lighthouse, crane and cannery all respond when you walk up, and there is a live leaderboard and guestbook.', array['Three.js','第一 / 第三人称','昼夜循环','在线排行榜']::text[], array['Three.js','First / third person','Day-night cycle','Live leaderboard']::text[], '[{"n":"5","zh":"个区域","en":"districts"},{"n":"1126","zh":"个资产实例","en":"asset instances"},{"n":"10′","zh":"一个昼夜","en":"per day cycle"}]'::jsonb, 'Three.js r186 · Supabase', 'Vercel');
insert into public.vault_ideas (sort, category, status, year, hue, url, repo, images, title_zh, title_en, kind_zh, kind_en, line_zh, line_en, lead_zh, lead_en, tags_zh, tags_en, facts, tech, host) values (20, '2d', 'live', 2026, '#3fb8a8', 'https://sugarvei.github.io/koi-pond/', 'https://github.com/SugarVei/koi-pond', array['assets/koi-1.jpg','assets/koi-2.jpg','assets/koi-3.jpg']::text[], '锦池', 'Koi Pond', '交互网页', 'Interactive web', '一池可以触摸的水。划过水面泛起涟漪，靠近锦鲤会游过来，轻点一下投下鱼食。', 'A pond you can touch: ripples follow your cursor, koi swim over to you, and a tap drops food.', '涟漪来自实时的水面波动模拟，水底的光纹会跟着弯折；每条锦鲤都有自己的巡游、靠近、抢食和散开。没人操作的时候，水面也会偶尔自己泛起涟漪。', 'Ripples come from a real-time wave simulation that bends the light on the pond floor. Each koi cruises, approaches, feeds and scatters on its own, and the water stirs now and then even when no one is touching it.', array['Canvas 2D','水波模拟','鱼群行为']::text[], array['Canvas 2D','Wave simulation','Fish behaviour']::text[], '[{"n":"3","zh":"种交互","en":"interactions"},{"n":"60Hz","zh":"水波计算","en":"wave solver"},{"n":"1","zh":"个 HTML 文件","en":"HTML file"}]'::jsonb, 'Canvas 2D', 'GitHub Pages');
insert into public.vault_ideas (sort, category, status, year, hue, url, repo, images, title_zh, title_en, kind_zh, kind_en, line_zh, line_en, lead_zh, lead_en, tags_zh, tags_en, facts, tech, host) values (30, '3d', 'live', 2026, '#4a7bd0', 'https://little-earth-livid.vercel.app', null, array['assets/earth-0.jpg','assets/earth-2.jpg','assets/earth-3.jpg','assets/earth-4.jpg']::text[], '小小世界', 'Little Earth', '3D 微缩地球', '3D miniature globe', '远看是一颗完整的小地球，拉近就进入城市和地貌的立体沙盘。', 'From afar it is a whole tiny planet; zoom in and you land in a 3D diorama of a city or landscape.', '18 座城市、12 类自然地貌，共 30 个沙盘。地球俯冲到目的地后，沙盘从平面隆起，楼宇生长、树木冒出；可以切换清晨、正午、黄昏、夜晚，开启环游世界自动导览，或把当前视角冲印成明信片。', '30 dioramas: 18 cities and 12 kinds of landscape. Fly down to a place and the ground rises, buildings grow and trees sprout. Switch between dawn, noon, dusk and night, take an automatic world tour, or print the current view as a postcard.', array['Three.js','30 个沙盘','晨昏光影','明信片']::text[], array['Three.js','30 dioramas','Time of day','Postcards']::text[], '[{"n":"18","zh":"座城市","en":"cities"},{"n":"12","zh":"类地貌","en":"landscapes"},{"n":"4","zh":"种光影","en":"lighting moods"}]'::jsonb, 'Three.js', 'Vercel');
